//! `ferrule setup install`: the `.ferrule/` directory and the thin files each
//! agent host reads, generated from templates inside the binary.
//!
//! Every generated file, and every marked block ferrule keeps inside a
//! project file, is hashed in `.ferrule/ferrule.lock`. Re-running install
//! upgrades: a file whose hash still matches the lock is replaced, one
//! someone edited is kept and the new version lands next to it as
//! `<name>.ferrule-new`. A file at a generated path that ferrule never
//! wrote is refused unless forced.

mod githooks;
mod items;
mod lock;
mod markers;
mod project;
mod settings;
mod uninstall;
mod version;

