pub const VERSION: &str = env!("CARGO_PKG_VERSION");

const LOCK: &str = ".ferrule/ferrule.lock";

const CONFIG: &str = ".ferrule/ferrule.toml";
const GENERATED: &str = "generated by ferrule";

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Stack {
    Rust,
    Node,
    Go,
    Python,
    None,
}

impl Stack {
    #[must_use]
    pub fn parse(s: &str) -> Option<Stack> {
        Some(match s {
            "rust" => Stack::Rust,
            "node" => Stack::Node,
            "go" => Stack::Go,
            "python" => Stack::Python,
            "none" => Stack::None,
            _ => return None,
        })
    }

    #[must_use]
    pub fn as_str(self) -> &'static str {
        match self {
            Stack::Rust => "rust",
            Stack::Node => "node",
            Stack::Go => "go",
            Stack::Python => "python",
            Stack::None => "none",
        }
    }

    /// From the build file at the project root.
    #[must_use]
    pub fn detect(root: &Path) -> Stack {
        let has = |f: &str| root.join(f).is_file();
        if has("Cargo.toml") {
            Stack::Rust
        } else if has("package.json") {
            Stack::Node
        } else if has("go.mod") {
            Stack::Go
        } else if has("pyproject.toml") || has("setup.py") {
            Stack::Python
        } else {
            Stack::None
        }
    }

    /// The `[[gauntlet.step]]`s a new `ferrule.toml` starts with.
    fn gauntlet(self) -> &'static [(&'static str, &'static str)] {
        match self {
            Stack::Rust => &[
                ("fmt", r#"["cargo", "fmt", "--check"]"#),
                (
                    "clippy",
                    r#"["cargo", "clippy", "--workspace", "--all-targets", "--", "-D", "warnings"]"#,
                ),
                ("test", r#"["cargo", "test", "--workspace"]"#),
            ],
            Stack::Node => &[("test", r#"["npm", "test"]"#)],
            Stack::Go => &[
                ("vet", r#"["go", "vet", "./..."]"#),
                ("test", r#"["go", "test", "./..."]"#),
            ],
            Stack::Python => &[("test", r#"["python", "-m", "pytest"]"#)],
            Stack::None => &[],
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Hooks {
    /// Through the project's lefthook configuration.
    Lefthook,
    /// Written into the repository's hooks directory.
    Git,
    /// Another hook manager: the user wires them up.
    Manual,
}

impl Hooks {
    #[must_use]
    pub fn as_str(self) -> &'static str {
        match self {
            Hooks::Lefthook => "lefthook",
            Hooks::Git => "git",
            Hooks::Manual => "manual",
        }
    }
}

#[derive(Debug, Clone, Default)]
pub struct Options {
    pub stack: Option<Stack>,
    pub force: bool,
}

#[derive(Debug)]
pub enum Error {
    Io(std::io::Error),
    /// A file at a generated path that ferrule never wrote.
    Foreign(String),
    /// `.claude/settings.json` that is not a JSON object.
    Settings(String),
    Lock(String),
    /// `ferrule.toml` that does not load.
    Config(String),
    /// A file whose ferrule block markers are unpaired or repeated: the
    /// path and what is wrong.
    Markers(String, String),
}

impl From<std::io::Error> for Error {
    fn from(e: std::io::Error) -> Self {
        Error::Io(e)
    }
}

impl Error {
    /// The `<verb>=refused` line: `foreign` names the path, the others say
    /// what was wrong in `detail=`.
    #[must_use]
    pub fn refusal(&self, verb: &'static str) -> Refusal {
        const FIX: &str = "fix the file the detail names, then rerun";
        match self {
            Error::Foreign(p) => Refusal::new(verb, "foreign")
                .field("path", p)
                .hint("--force overwrites it"),
            Error::Settings(_) => Refusal::new(verb, "settings")
                .detail(self.to_string())
                .hint(FIX),
            Error::Lock(_) => Refusal::new(verb, "lock")
                .detail(self.to_string())
                .hint(FIX),
            Error::Config(_) => Refusal::new(verb, "config")
                .detail(self.to_string())
                .hint(FIX),
            Error::Markers(p, _) => Refusal::new(verb, "markers")
                .field("path", p)
                .detail(self.to_string())
                .hint("leave one begin and one end marker in the file, then rerun"),
            Error::Io(_) => Refusal::new(verb, "io").detail(self.to_string()).hint(FIX),
        }
    }
}

impl std::fmt::Display for Error {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Error::Io(e) => write!(f, "{e}"),
            Error::Foreign(p) => write!(f, "{p} exists and ferrule did not write it"),
            Error::Settings(e) => write!(f, ".claude/settings.json: {e}"),
            Error::Lock(e) => write!(f, "{LOCK}: {e}"),
            Error::Config(e) => write!(f, "{CONFIG}: {e}"),
            Error::Markers(p, e) => write!(f, "{p}: {e}"),
        }
    }
}

impl std::error::Error for Error {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            Error::Io(e) => Some(e),
            Error::Foreign(_)
            | Error::Settings(_)
            | Error::Lock(_)
            | Error::Config(_)
            | Error::Markers(..) => None,
        }
    }
}

/// What install did, in the order it did it.
#[derive(Debug, Default)]
pub struct Report {
    pub written: Vec<String>,
    /// Edited files kept: (path, the `.ferrule-new` path, `+a/-b`).
    pub kept: Vec<(String, String, String)>,
    pub hints: Vec<String>,
    pub stack: Option<Stack>,
    pub hooks: Option<Hooks>,
    pub viewer: bool,
}

fn write(root: &Path, path: &str, text: &str, exec: bool) -> std::io::Result<()> {
    let full = root.join(path);
    if let Some(dir) = full.parent() {
        std::fs::create_dir_all(dir)?;
    }
    std::fs::write(&full, text)?;
    if exec {
        set_exec(&full)?;
    }
    Ok(())
}

#[cfg(unix)]
fn set_exec(path: &Path) -> std::io::Result<()> {
    use std::os::unix::fs::PermissionsExt;
    let mut p = std::fs::metadata(path)?.permissions();
    p.set_mode(p.mode() | 0o755);
    std::fs::set_permissions(path, p)
}

#[cfg(not(unix))]
fn set_exec(_: &Path) -> std::io::Result<()> {
    Ok(())
}

/// `+a/-b`: lines only the new text has, lines only the old one has.
fn diff_summary(old: &str, new: &str) -> String {
    let mut counts: BTreeMap<&str, i64> = BTreeMap::new();
    for l in new.lines() {
        *counts.entry(l).or_default() += 1;
    }
    for l in old.lines() {
        *counts.entry(l).or_default() -= 1;
    }
    let added: i64 = counts.values().filter(|&&c| c > 0).sum();
    let removed: i64 = -counts.values().filter(|&&c| c < 0).sum::<i64>();
    format!("+{added}/-{removed}")
}

/// Sets up or upgrades the project at `root`.
///
/// # Errors
/// [`Error::Foreign`] before anything is written when a generated path
/// holds a file ferrule did not write and `force` is off.
pub fn install(root: &Path, opts: &Options) -> Result<Report, Error> {
    let mut lock = Lock::load(root)?;
    // Everything that could refuse is read before anything is written.
    if root.join(CONFIG).exists() {
        config::Config::load(root).map_err(|e| Error::Config(e.to_string()))?;
    }
    settings::validate(root)?;
    let items = items(root);
    check_markers(root, &items)?;
    if !opts.force {
        for item in &items {
            if let (Item::File { path, text, .. }, Some(cur)) = (item, item.current(root))
                && cur != *text
                && !lock.files.contains_key(path)
            {
                return Err(Error::Foreign(path.clone()));
            }
        }
    }
    let mut report = Report::default();
    ensure_config(root, opts, &mut report)?;
    for item in &items {
        apply(root, item, &mut lock, &mut report)?;
    }
    let config = config::Config::load(root).map_err(|e| Error::Config(e.to_string()))?;
    if settings::apply(root, &deny_rules(&config.guard.allow), &mut lock.deny)? {
        report.written.push(settings::PATH.to_owned());
    }
    ensure_claude_md(root, &mut lock, &mut report)?;
    if !root.join("docs/specs/README.md").exists() {
        write(root, "docs/specs/README.md", SPECS_README, false)?;
        report.written.push("docs/specs/README.md".to_owned());
    }
    ensure_git_hooks(root, &mut report)?;
    if !report.viewer {
        report.hints.push("hint=no viewer: prompt show prints approval files into the agent's context; install glow and rerun ferrule setup install".to_owned());
    }
    VERSION.clone_into(&mut lock.version);
    let text = lock.text();
    if std::fs::read_to_string(root.join(LOCK)).ok().as_deref() != Some(text.as_str()) {
        write(root, LOCK, &text, false)?;
    }
    Ok(report)
}

fn apply(root: &Path, item: &Item, lock: &mut Lock, report: &mut Report) -> std::io::Result<()> {
    let key = item.key();
    let new = item.expected();
    let exec = matches!(item, Item::File { exec: true, .. });
    match item.current(root) {
        Some(cur) if cur == new => {}
        Some(cur) if lock.files.get(&key).is_some_and(|h| *h != hash(&cur)) => {
            let side = format!("{}.ferrule-new", item.path());
            write(root, &side, &item.render(root), exec)?;
            report
                .kept
                .push((item.path().to_owned(), side, diff_summary(&cur, &new)));
            return Ok(());
        }
        _ => {
            write(root, item.path(), &item.render(root), exec)?;
            report.written.push(item.path().to_owned());
        }
    }
    // The file is ferrule's version now: a side copy of an earlier one is
    // stale.
    let side = root.join(format!("{}.ferrule-new", item.path()));
    if side.is_file() {
        std::fs::remove_file(side)?;
    }
    lock.files.insert(key, hash(&new));
    Ok(())
}

/// The `permissions.deny` backstop: every replaced command the project
/// did not re-open, and the files only ferrule writes. A command gets an
/// exact rule and one for it followed by arguments: `git merge:*` alone
/// would also match `git merge-base`.
#[must_use]
pub fn deny_rules(allow: &[String]) -> Vec<String> {
    let mut out: Vec<String> = guard::REPLACED
        .iter()
        .filter(|r| !reopened(r.raw, allow))
        .flat_map(|r| [format!("Bash({})", r.raw), format!("Bash({} :*)", r.raw)])
        .collect();
    for path in [
        "**/.ferrule/state.db",
        "**/.ferrule/ferrule.lock",
        "**/.ferrule/ferrule.toml",
        "**/.claude/settings.json",
        "**/.claude/settings.local.json",
        "**/.claude/agents/fe-*.md",
        "**/.claude/skills/fe-*/SKILL.md",
    ] {
        // An `Edit` rule covers every tool that writes files, `Write` included.
        out.push(format!("Edit({path})"));
    }
    out
}

/// Whether `[guard] allow` re-opens the whole of `raw`, as the guard reads
/// it: an entry's words must be a word prefix of the command. A longer
/// entry (`git push --dry-run`) re-opens one form only, which a deny rule
/// cannot express, so the rule stays.
fn reopened(raw: &str, allow: &[String]) -> bool {
    let words: Vec<&str> = raw.split_whitespace().collect();
    allow.iter().any(|a| {
        let a: Vec<&str> = a.split_whitespace().collect();
        !a.is_empty() && words.starts_with(&a)
    })
}

/// Where the project drifted from what this binary would write: one
/// `path=… reason=…` each, empty when in step.
///
/// # Errors
/// An unreadable lock or settings file.
pub fn check(root: &Path) -> Result<Vec<String>, Error> {
    let lock = Lock::load(root)?;
    check_markers(root, &items(root))?;
    let mut drift = Vec::new();
    let pinned = config::Config::load(root).ok().and_then(|c| c.version);
    if pinned.as_deref() != Some(VERSION) {
        drift.push(format!(
            "path={CONFIG} reason=version pinned={} binary={VERSION}",
            pinned.as_deref().unwrap_or("none")
        ));
    }
    if lock.version != VERSION {
        drift.push(format!(
            "path={LOCK} reason=version locked={} binary={VERSION}",
            if lock.version.is_empty() {
                "none"
            } else {
                &lock.version
            }
        ));
    }
    for item in items(root) {
        let new = item.expected();
        let reason = match item.current(root) {
            None => Some("missing"),
            Some(cur) if cur == new => None,
            Some(cur) => Some(
                if lock
                    .files
                    .get(&item.key())
                    .is_some_and(|h| *h == hash(&cur))
                {
                    "stale"
                } else {
                    "edited"
                },
            ),
        };
        if let Some(r) = reason {
            drift.push(format!("path={} reason={r}", item.path()));
        }
    }
    let config = match config::Config::load(root) {
        Ok(c) => c,
        Err(_) if !root.join(CONFIG).exists() => config::Config::default(),
        Err(e) => return Err(Error::Config(e.to_string())),
    };
    if !settings::in_step(root, &deny_rules(&config.guard.allow), &lock.deny)? {
        drift.push(format!("path={} reason=edited", settings::PATH));
    }
    Ok(drift)
}

#[cfg(test)]
mod tests {
    use super::markers::{block, marker_problem};
    use super::project::{config_text, pin_version};
    use super::*;

    #[test]
    fn ut_markers_crlf_and_problems() {
        let crlf = "a\r\n# ferrule:begin\r\nx\r\n# ferrule:end\r\nb\r\n";
        let (s, e) = block(crlf, "# ferrule:begin", "# ferrule:end").unwrap();
        assert_eq!(&crlf[s..e], "# ferrule:begin\r\nx\r\n# ferrule:end\r\n");
        let p = |t| marker_problem(t, "# ferrule:begin", "# ferrule:end");
        assert_eq!(p(crlf), None);
        assert!(p("# ferrule:begin\nx\n").is_some());
        assert!(p("x\n# ferrule:end\n").is_some());
        assert!(p("# ferrule:end\n# ferrule:begin\n").is_some());
        assert!(p("# ferrule:begin\n# ferrule:end\n# ferrule:begin\n# ferrule:end\n").is_some());
    }

    #[test]
    fn ut_pin_version_touches_the_top_level_key_only() {
        let v = "version = \"9\"";
        assert_eq!(
            pin_version(
                "version = \"1\"\r\nstack = \"rust\"\r\n[x]\r\nversion = 3\r\n",
                v
            ),
            "version = \"9\"\r\nstack = \"rust\"\r\n[x]\r\nversion = 3\r\n"
        );
        assert_eq!(
            pin_version("stack = \"rust\"\n[x]\nversion = 3\n", v),
            "version = \"9\"\nstack = \"rust\"\n[x]\nversion = 3\n"
        );
    }

    #[test]
    fn ut_block_spans_its_markers() {
        let t = "a\n# ferrule:begin\nx\n# ferrule:end\nb\n";
        let (s, e) = block(t, "# ferrule:begin", "# ferrule:end").unwrap();
        assert_eq!(&t[s..e], "# ferrule:begin\nx\n# ferrule:end\n");
        assert_eq!(
            block("x # ferrule:begin\n", "# ferrule:begin", "# ferrule:end"),
            None
        );
    }

    #[test]
    fn ut_diff_summary_counts_lines() {
        assert_eq!(diff_summary("a\nb\nc\n", "a\nc\nd\ne\n"), "+2/-1");
    }

    #[test]
    fn ut_hash_is_fnv1a() {
        assert_eq!(hash(""), "cbf29ce484222325");
        assert_eq!(hash("a"), "af63dc4c8601ec8c");
    }

    #[test]
    fn ut_deny_rules_skip_reopened_commands() {
        let all = deny_rules(&[]);
        assert!(all.contains(&"Bash(git commit)".to_owned()));
        assert!(all.contains(&"Bash(git commit :*)".to_owned()));
        assert!(!all.iter().any(|r| r.starts_with("Bash(git merge:")));
        assert!(all.contains(&"Edit(**/.ferrule/state.db)".to_owned()));
        assert!(!all.iter().any(|r| r.starts_with("Write(")));
        let some = deny_rules(&["gh issue".to_owned()]);
        assert!(!some.iter().any(|r| r.starts_with("Bash(gh issue")));
        assert!(some.contains(&"Bash(gh pr create :*)".to_owned()));
    }

    #[test]
    fn ut_deny_rules_match_allow_by_words() {
        let has = |rules: &[String], raw: &str| rules.contains(&format!("Bash({raw} :*)"));
        let partial = deny_rules(&["gh iss".to_owned()]);
        assert!(has(&partial, "gh issue view"));
        let whole = deny_rules(&["gh issue".to_owned()]);
        assert!(!has(&whole, "gh issue view"));
        let longer = deny_rules(&["git push --dry-run".to_owned()]);
        assert!(has(&longer, "git push"));
    }

    #[test]
    fn ut_config_text_parses() {
        let c: config::Config = toml::from_str(&config_text(Stack::Rust, "trunk", true)).unwrap();
        assert_eq!(c.version.as_deref(), Some(VERSION));
        assert_eq!(c.main_branch, "trunk");
        assert_eq!(c.gauntlet.step.len(), 3);
        assert_eq!(c.viewer.command, Some(vec!["glow".to_owned()]));
    }
}
